import type { CSSProperties } from 'react';
import './animated-bar-chart.css';

export interface BarDatum {
  /** Stable key: bars keep their identity and color across datasets. */
  id: string;
  label: string;
  value: number;
}

export interface AnimatedBarChartProps {
  data: BarDatum[];
  /** Top of the scale. Keep it fixed so bars compare across datasets. */
  max: number;
  unit?: string;
  /** Accessible name, for example "Wind speed by day". */
  label: string;
  className?: string;
}

/**
 * Bars grow or shrink to new values, keyed by `id` so each category keeps its
 * place. Every bar prints its exact value. Rapid changes simply retarget.
 */
export function AnimatedBarChart({
  data,
  max,
  unit = '',
  label,
  className = '',
}: AnimatedBarChartProps) {
  return (
    <figure className={`mg-bars ${className}`}>
      <figcaption className='mg-bars__caption'>{label}</figcaption>
      <ul className='mg-bars__list'>
        {data.map((d) => (
          <li
            key={d.id}
            className='mg-bars__item'
            style={
              {
                '--mg-value': Math.max(0, Math.min(1, d.value / max)),
              } as CSSProperties
            }
          >
            <span className='mg-bars__value'>
              {d.value}
              {unit}
            </span>
            <span className='mg-bars__track' aria-hidden='true'>
              <span className='mg-bars__bar' />
            </span>
            <span className='mg-bars__label'>{d.label}</span>
          </li>
        ))}
      </ul>
    </figure>
  );
}

.mg-bars {
  margin: 0;
  color: var(--mg-text, #ffffff);
}

.mg-bars__caption {
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 700;
}

.mg-bars__list {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-bars__item {
  display: grid;
  grid-template-rows: auto 140px auto;
  gap: 4px;
  justify-items: center;
}

.mg-bars__value {
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.mg-bars__track {
  position: relative;
  width: 100%;
  border-bottom: 2px solid var(--mg-text, #ffffff);
}

.mg-bars__bar {
  position: absolute;
  right: 18%;
  bottom: 0;
  left: 18%;
  height: 100%;
  border-radius: 6px 6px 0 0;
  background: var(--mg-accent, #eaf2fb);
  transform: scaleY(var(--mg-value));
  transform-origin: bottom;
  transition: transform 500ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-bars__item:nth-child(odd) .mg-bars__bar {
  background: #eaf2fb;
}

.mg-bars__label {
  color: #b8b8b8;
  font-size: 12px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-bars__bar {
    transition: none;
  }
}
